package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.EnvironmentVO;

class EnvironmentValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of environment of observed source")
  void test_environment_value_holder_assign_plain_value() {
    Object holder = new Object();
    EnvironmentValueHolder<Object> value = new EnvironmentValueHolder<>(holder);
    Assertions.assertSame(holder, value.environment("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getEnvironmentValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getEnvironment().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.environmentNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getEnvironmentValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getEnvironment().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of environment of observed source")
  void test_environment_value_holder_assign_value_object() {
    Object holder = new Object();
    EnvironmentValueHolder<Object> value = new EnvironmentValueHolder<>(holder);
    EnvironmentVO vo = EnvironmentVO.from("one");
    Assertions.assertFalse(value.getEnvironmentValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.environment(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getEnvironmentValue().orElseThrow());
    Assertions.assertSame(holder, value.environment(Optional.empty()));
    Assertions.assertFalse(value.getEnvironmentValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.environment(Optional.of(vo)));
    Assertions.assertSame(vo, value.getEnvironmentValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of environment of observed source against the original")
  void test_environment_value_holder_read() {
    Object holder = new Object();
    EnvironmentValueHolder<Object> value = new EnvironmentValueHolder<>(holder);
    EnvironmentVO vo = EnvironmentVO.from("one");
    EnvironmentVO other = EnvironmentVO.from("one");
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getEnvironmentValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readEnvironment(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readEnvironment(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.environment(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readEnvironment(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readEnvironment(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of environment of observed source")
  void test_environment_value_holder_unset() {
    Object holder = new Object();
    EnvironmentValueHolder<Object> value = new EnvironmentValueHolder<>(holder);
    EnvironmentVO vo = EnvironmentVO.from("one");
    value.environment(vo);
    Assertions.assertSame(holder, value.unsetEnvironmentIfMatches("environment_other"));
    Assertions.assertTrue(value.getEnvironmentValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetEnvironmentIfMatches("environment"));
    Assertions.assertFalse(value.getEnvironmentValue().isPresent(),
        "The field name must clear the value");
    value.environment(vo);
    Assertions.assertSame(holder, value.unsetEnvironment());
    Assertions.assertFalse(value.getEnvironmentValue().isPresent(), "Unset must clear the value");
  }
}
